dataTableFormat:
{
  "is multi section": "true",
  "sections": [
    {
      "section id": "SingleCell",
      "data point": {
        "type": "api",
        "url": "https://sympatlas.hugeampkpnbi.org/api/raw/file/single_cell_all_metadata/dataset_metadata.json.gz",
        "data type": "line json"
      },
      "visualizer": {
        "type": "cell browser",
        "label": "Single Cell Browser",
        "parameters":{
          "datasetId": "datasetId",
          "gene": "gene"
        },
        "presets":{
         "datasetId": "sympatlas_scRNA",
         "showDatasetSelect": false
        },

        "bioIndex": "https://sympatlas.hugeampkpnbi.org",
        "bioIndexDev": "https://sympatlas.hugeampkpnbi.org",

        "format":{
          "sympatlas_scRNA":{
            "stratifyPlotType": null,
            "expressionColorScale": "red",
            "dotPlotColorScaleMode": "scaled-per-gene",
            "preserveMarkerGeneOrder": true,
            "groups": {
              "cellType": [
                "Ganglion", 
                "cell_type__kp"
              ]
            },
            "displayMap": {
              "final_clusters":{
                "display": false,
                "displayName": "final_clusters ID",
                "dataType": "cat"
              },
              "Dataset":{
                "display": true,
                "displayName": "Dataset",
                "dataType": "cat"
              },
              "Species":{
                "display": true,
                "displayName": "Species",
                "dataType": "cat"
              },
              "Ganglion":{
                "display": true,
                "displayName": "Ganglion",
                "dataType": "cat",
                "customSortOrder": ["SCG","Stellate","ThoracicPool","Lumbar","Coeliac","Pelvic"]
              },
              "Chemistry":{
                "display": false,
                "displayName": "Chemistry",
                "dataType": "cat"
              },
              "Preparation type":{
                "display": false,
                "displayName": "Preparation type",
                "dataType": "cat"
              },
              "cell_type__author":{
                "display": false,
                "displayName": "Cell type (author)",
                "dataType": "cat",
                "excludeReason": "redundant"
              },
              "cell_type__kp":{
                "display": true,
                "displayName": "Cell Type (portal)",
                "dataType": "cat",
                "customSortOrder": ["Nor18","Nor20","Nor16","Nor17","Nor5","Ch2","Ch3","Ch1","Ch5","Ch4","Nor19","Nor3","Nor6","Nor4","NPC","Neurobl.","Nor11","Nor2","Ch. neurobl.","Ch6","Glut.","Nor1","Nor7","Nor8","Nor10","Nor21","AGRP","Nor12","Nor9","Nor13","Nor14","Nor15"]
              },
              "cell_type__ontology_id":{
                "display": false,
                "displayName": "cell_type__ontology_id",
                "dataType": "cat",
                "excludeReason": "ontology"
              },
              "cell_type__ontology_label":{
                "display": false,
                "displayName": "cell_type__ontology_label",
                "dataType": "cat",
                "excludeReason": "ontology"
              }
            }
          }

        }
      }
    }
  ]
}
